import pandas as pd

def create_gantt_chart(project):
    tasks = project.tasks.all()
    if not tasks:
        return None

    df = pd.DataFrame([{
        'Task': task.name,
        'Start': task.start_date,
        'Finish': task.end_date,
        'Status': task.get_status_display(),
    } for task in tasks])

    fig = px.timeline(df, x_start="Start", x_end="Finish", y="Task", color="Status")
    fig.update_yaxes(autorange="reversed")
    return fig.to_html(full_html=False, default_height=500, include_plotlyjs='cdn')

