import plotly.graph_objects as go
import pandas as pd
from collections import defaultdict
from datetime import timedelta

def get_all_tasks(project):
    tasks = []
    def recurse_tasks(task, level):
        tasks.append({
            'task': task,
            'level': level
        })
        for subtask in task.subtasks.all().order_by('start_date'):
            recurse_tasks(subtask, level + 1)

    for task in project.tasks.filter(parent_task__isnull=True).order_by('start_date'):
        recurse_tasks(task, 0)
    return tasks

def calculate_schedule_metrics(project):
    tasks = list(project.tasks.all())
    if not tasks:
        return {}, {}

    task_map = {task.id: task for task in tasks}
    adj = defaultdict(list)
    rev_adj = defaultdict(list)
    for task in tasks:
        for dep in task.dependencies.all():
            adj[dep.id].append(task.id)
            rev_adj[task.id].append(dep.id)

    # Calculate Earliest Start (ES) and Earliest Finish (EF)
    es = {task.id: 0 for task in tasks}
    for task in tasks:
        if not task.dependencies.exists() and not task.parent_task:
            es[task.id] = 1 # Start day 1

    sorted_tasks = []
    in_degree = {t.id: t.dependencies.count() for t in tasks}
    queue = [t.id for t in tasks if in_degree[t.id] == 0]
    while queue:
        task_id = queue.pop(0)
        sorted_tasks.append(task_id)
        for dependent_task_id in adj[task_id]:
            in_degree[dependent_task_id] -= 1
            if in_degree[dependent_task_id] == 0:
                queue.append(dependent_task_id)

    for task_id in sorted_tasks:
        task = task_map[task_id]
        duration = (task.end_date - task.start_date).days + 1
        max_pred_ef = 0
        for pred_id in rev_adj[task_id]:
            pred_task = task_map[pred_id]
            pred_duration = (pred_task.end_date - pred_task.start_date).days + 1
            max_pred_ef = max(max_pred_ef, es[pred_id] + pred_duration)
        es[task_id] = max_pred_ef + 1

    ef = {t_id: es[t_id] + ((task_map[t_id].end_date - task_map[t_id].start_date).days) for t_id in es}

    project_finish_time = max(ef.values()) if ef else 0

    # Calculate Latest Start (LS) and Latest Finish (LF)
    lf = {task.id: project_finish_time for task in tasks}
    ls = {t_id: lf[t_id] - ((task_map[t_id].end_date - task_map[t_id].start_date).days) for t_id in lf}

    for task_id in reversed(sorted_tasks):
        for pred_id in rev_adj[task_id]:
            pred_duration = (task_map[pred_id].end_date - task_map[pred_id].start_date).days + 1
            lf[pred_id] = min(lf[pred_id], ls[task_id] - 1)
            ls[pred_id] = lf[pred_id] - pred_duration + 1

    # Calculate Slack and Critical Path
    slack = {t_id: ls[t_id] - es[t_id] for t_id in es}
    critical_path_ids = {t_id for t_id, s in slack.items() if s == 0}

    return critical_path_ids, slack

def create_gantt_chart(project):
    tasks_with_levels = get_all_tasks(project)
    if not tasks_with_levels:
        return None

    critical_path_ids, slack_days = calculate_schedule_metrics(project)

    df_data = []
    for item in tasks_with_levels:
        task = item['task']
        level = item['level']
        is_summary = task.subtasks.exists()

        start_date = task.start_date
        end_date = task.end_date
        if is_summary:
            sub_tasks = get_all_tasks(task)
            if sub_tasks:
                start_date = min(t['task'].start_date for t in sub_tasks)
                end_date = max(t['task'].end_date for t in sub_tasks)

        df_data.append({
            'Task': '&nbsp;' * 4 * level + task.name,
            'Start': start_date,
            'Finish': end_date,
            'id': task.id,
            'is_summary': is_summary,
            'is_critical': task.id in critical_path_ids,
            'slack': slack_days.get(task.id, 0)
        })

    df = pd.DataFrame(df_data)
    df = df.sort_values(by=['Start', 'Task'], ascending=False).reset_index(drop=True)

    fig = go.Figure()

    # Add Slack bars
    for i, row in df.iterrows():
        if not row['is_summary'] and row['slack'] > 0:
            fig.add_trace(go.Bar(
                y=[row['Task']], x=[row['Finish'] + timedelta(days=row['slack'])],
                base=[row['Finish']], orientation='h',
                marker_color='rgba(0, 0, 255, 0.2)',
                showlegend=False, hoverinfo='text',
                text=f"Slack: {row['slack']} days"
            ))

    # Add Task bars
    for i, row in df.iterrows():
        if not row['is_summary']:
            color = '#d62728' if row['is_critical'] else '#1f77b4'
            fig.add_trace(go.Bar(
                y=[row['Task']], x=[row['Finish']], base=[row['Start']],
                orientation='h', marker_color=color, name='Critical Task' if row['is_critical'] else 'Task',
                showlegend=(i==0), text=row['Task'], textposition='inside'
            ))

    # Add Summary task markers
    for i, row in df.iterrows():
        if row['is_summary']:
            fig.add_trace(go.Scatter(
                x=[row['Start'], row['Finish']], y=[row['Task'], row['Task']],
                mode='lines+markers', line=dict(color='black', width=2),
                marker=dict(symbol='triangle-down', color='black', size=10),
                name='Summary Task', showlegend=(i==0)
            ))

    # Add dependency arrows
    arrows = []
    task_y_mapping = {row['Task']: i for i, row in df.iterrows()}
    for i, row in df.iterrows():
        task = project.tasks.get(id=row['id'])
        for dep in task.dependencies.all():
            dep_row = df[df['id'] == dep.id]
            if not dep_row.empty:
                dep_y = task_y_mapping[dep_row.iloc[0]['Task']]
                task_y = task_y_mapping[row['Task']]
                arrows.append(go.layout.Annotation(
                    ax=dep_row.iloc[0]['Finish'], ay=dep_y, axref='x', ayref='y',
                    x=row['Start'], y=task_y, xref='x', yref='y',
                    showarrow=True, arrowhead=2, arrowsize=1, arrowwidth=1, arrowcolor='grey'
                ))

    fig.update_layout(
        title_text=f'Gantt Chart: {project.name}',
        xaxis_title='Date',
        yaxis_title=None,
        legend_title='Legend',
        barmode='overlay',
        annotations=arrows,
        plot_bgcolor='white',
        yaxis=dict(showgrid=True, gridcolor='lightgrey'),
        xaxis=dict(showgrid=True, gridcolor='lightgrey')
    )

    return fig.to_html(full_html=False, default_height=len(df)*30 + 150, include_plotlyjs='cdn')

