import plotly.graph_objects as go
import pandas as pd
from collections import defaultdict
from datetime import timedelta

def get_all_tasks(project):
    tasks = []
    def recurse_tasks(task, level):
        tasks.append({
            'task': task,
            'level': level
        })
        for subtask in task.subtasks.all().order_by('start_date'):
            recurse_tasks(subtask, level + 1)

    for task in project.tasks.filter(parent_task__isnull=True).order_by('start_date'):
        recurse_tasks(task, 0)
    return tasks

def calculate_schedule_metrics(project):
    tasks = list(project.tasks.all())
    if not tasks:
        return {}, {}

    task_map = {task.id: task for task in tasks}
    adj = defaultdict(list)
    rev_adj = defaultdict(list)
    for task in tasks:
        for dep in task.dependencies.all():
            adj[dep.id].append(task.id)
            rev_adj[task.id].append(dep.id)

    # Calculate Earliest Start (ES) and Earliest Finish (EF)
    es = {task.id: 0 for task in tasks}
    for task in tasks:
        if not task.dependencies.exists() and not task.parent_task:
            es[task.id] = 1 # Start day 1

    sorted_tasks = []
    in_degree = {t.id: t.dependencies.count() for t in tasks}
    queue = [t.id for t in tasks if in_degree[t.id] == 0]
    while queue:
        task_id = queue.pop(0)
        sorted_tasks.append(task_id)
        for dependent_task_id in adj[task_id]:
            in_degree[dependent_task_id] -= 1
            if in_degree[dependent_task_id] == 0:
                queue.append(dependent_task_id)

    for task_id in sorted_tasks:
        task = task_map[task_id]
        duration = (task.end_date - task.start_date).days + 1
        max_pred_ef = 0
        for pred_id in rev_adj[task_id]:
            pred_task = task_map[pred_id]
            pred_duration = (pred_task.end_date - pred_task.start_date).days + 1
            max_pred_ef = max(max_pred_ef, es[pred_id] + pred_duration)
        es[task_id] = max_pred_ef + 1

    ef = {t_id: es[t_id] + ((task_map[t_id].end_date - task_map[t_id].start_date).days) for t_id in es}

    project_finish_time = max(ef.values()) if ef else 0

    # Calculate Latest Start (LS) and Latest Finish (LF)
    lf = {task.id: project_finish_time for task in tasks}
    ls = {t_id: lf[t_id] - ((task_map[t_id].end_date - task_map[t_id].start_date).days) for t_id in lf}

    for task_id in reversed(sorted_tasks):
        for pred_id in rev_adj[task_id]:
            pred_duration = (task_map[pred_id].end_date - task_map[pred_id].start_date).days + 1
            lf[pred_id] = min(lf[pred_id], ls[task_id] - 1)
            ls[pred_id] = lf[pred_id] - pred_duration + 1

    # Calculate Slack and Critical Path
    slack = {t_id: ls[t_id] - es[t_id] for t_id in es}
    critical_path_ids = {t_id for t_id, s in slack.items() if s == 0}

    return critical_path_ids, slack

